using System;
using System.Collections.Generic;
using UnityEngine;

namespace LabSorting.Sorting
{
    // Maps an item's full-detail mesh to cheaper meshes that share its UVs and normals: "mid" (about half the
    // triangles) and "far" (about a third). Generated by Editor/ItemMeshLodBuilder; read by ItemBatchRenderer.
    public sealed class ItemMeshLodMap : ScriptableObject
    {
        [Serializable] public struct Entry { public Mesh full; public Mesh far; public Mesh mid; }
        public Entry[] entries = Array.Empty<Entry>();

        public Dictionary<Mesh, Mesh> Build() => Pick(e => e.far);
        public Dictionary<Mesh, Mesh> BuildMid() => Pick(e => e.mid);

        Dictionary<Mesh, Mesh> Pick(Func<Entry, Mesh> level)
        {
            var map = new Dictionary<Mesh, Mesh>(entries.Length);
            foreach (var entry in entries)
            {
                var lod = level(entry);
                if (entry.full && lod && !map.ContainsKey(entry.full)) map.Add(entry.full, lod);
            }
            return map;
        }
    }
}
